              "h": "🦠 Listeria monocytogenesの特徴",
              "c": "<span class=\"kw\">Listeria</span>：Gram陽性桿菌、通性嫌気性菌<br/>感染源：未殺菌チーズ・生ハム・スモークサーモン（食品由来）<br/>リスク群：<span class=\"kw\">妊婦</span>・高齢者・免疫不全者・新生児<br/>合併症：羊膜炎・早産・新生児髄膜炎<br/><span class=\"kw4\">自然耐性：セファロスポリン系（全て）・キノロン系</span><br/><span class=\"kw\">有効薬：アンピシリン</span>（第一選択）、ST合剤（ただし妊婦後期は禁忌）"
