          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 1/3</span>75 歳の女性。人工膝関節置換術のため入院中である。<br/>現病歴：7 日前に右変形性膝関節症に対して人工膝関節置換術を実施し、入院中である。3 日前から右膝の疼痛を自<br/>覚していた。前日から鎮痛薬を内服したが、疼痛が増悪し歩行困難となった。また38℃台の発熱も出現した。<br/>既往歴：60 歳から高血圧症と糖尿病に対して内服治療中である。<br/>生活歴：65 歳まで小学校の教師をしていた。夫と2 人暮らし。アレルギー歴はない。<br/>家族歴：父が高血圧症、母が糖尿病。<br/>術後7 日目の現症：意識は清明。身長154cm、体重50kg。体温38.1℃。脈拍124/ 分、整。血圧88/50mmHg。呼吸<br/>数24/ 分。SpO2 96％（room air）。眼瞼結膜はやや貧血様で、眼球結膜に黄染を認めない。頭頸部に異常を認めな<br/>い。心音と呼吸音とに異常を認めない。腹部は平坦、軟で、肝・脾を触知しない。背部に異常を認めない。右膝は<br/>手術創周囲に発赤と腫脹があり、疼痛で可動が困難である。創部の離開や滲出液は認めない。他の部位に皮膚の異<br/>常を認めない。<br/>検査所見：尿所見：蛋白（±）、糖1 ＋、潜血（－）。血液所見：赤血球372 万、Hb 11.3g/dL、Ht 32％、白血球11,900（桿<br/>状核好中球12％、分葉核好中球79％、好酸球1％、単球2％、リンパ球6％）、血小板10 万、PT-INR 1.34（基準0.9<br/>～1.1）、血漿フィブリノゲン810mg/dL（基準186 ～355）、D ダイマー5.7μg/mL（基準1.0 以下）。血液生化学<br/>所見：総蛋白6.2g/dL、アルブミン3.0g/dL、総ビリルビン0.8mg/dL、AST 30U/L、ALT 20U/L、LD 220U/L（基<br/>準124 ～222）、ALP 104U/L（基準38 ～113）、γ-GT 29U/L（基準9 ～32）、CK 150U/L（基準41 ～153）、尿<br/>素窒素15mg/dL、クレアチニン0.6mg/dL、血糖228mg/dL、HbA1c 6.5％（基準4.9 ～6.0）。Na 138mEq/L、K<br/>3.8mEq/L、Cl 103mEq/L。CRP 34mg/dL。<br/>指導医と共に右膝関節穿刺を実施した。関節液のGram 染色所見を示す。</span><br/><strong>この時点で追加すべき検査はどれか。</strong>",
