          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 1/2</span>28 歳の男性。腹痛を主訴に来院した。<br/>現病歴：昨日から臍部を中心とした腹痛が出現し、その後、悪心、食欲不振を伴うようになった。今朝になって痛み<br/>が右下腹部に移動し、悪化したため受診した。<br/>既往歴：5 歳時に右鼠径ヘルニアで手術。<br/>生活歴：妻、子ども（3 歳）と同居。公務員。喫煙歴と飲酒歴はない。<br/>家族歴：父が58 歳時に脳梗塞を発症。<br/>現　症：意識は清明。身長176cm、体重68kg。体温37.0℃。脈拍88/ 分、整。血圧128/76mmHg。呼吸数18/ 分。<br/>SpO2 97％（room air）。眼瞼結膜と眼球結膜とに異常を認めない。心音と呼吸音とに異常を認めない。腹部は平坦<br/>で、右下腹部に圧痛を認めるが反跳痛は認めない。四肢に異常を認めない。<br/>検査所見：血液所見：赤血球360 万、Hb 12.1g/dL、Ht 38％、白血球10,200（好中球85％、好酸球1％、好塩基球1％、<br/>単球2％、リンパ球11％）、血小板28 万。血液生化学所見：AST 16U/L、ALT 18U/L、LD 178U/L（基準120 ～<br/>245）、ALP 106U/L（基準38 ～113）、尿素窒素12mg/dL、クレアチニン0.6mg/dL、Na 142mEq/L、K 4.2mEq/L、<br/>Cl 102mEq/L。CRP 2.6mg/dL。<br/>急性虫垂炎の診断スコアを表1 に、その診断スコア合計点別の尤度比を表2 に示す。<br/>表1　急性虫垂炎の診断スコア<br/>項目<br/>スコア<br/>腹痛部位の移動<br/>1<br/>食欲不振<br/>1<br/>悪心、嘔吐<br/>1<br/>右下腹部の圧痛<br/>2<br/>反跳痛<br/>1<br/>発熱（体温 ≧37.3℃）<br/>1<br/>末梢血白血球数 ≧10,000<br/>2<br/>好中球 ≧75％<br/>1<br/>表2　診断スコア合計点別の尤度比<br/>スコア合計<br/>陽性尤度比<br/>0 ～4 点<br/>1.0<br/>5 ～6 点<br/>1.6<br/>7 点以上<br/>3.0</span><br/><strong>若年男性の急性の腹痛における急性虫垂炎の有病率が50％である場合、この患者における急性虫垂炎の確率はどれか。</strong>",
