          "qt": "<span class=\"qt-context\"><span class=\"series-label\">連問 2/3</span>43 歳の男性。発熱を主訴に来院した。<br/>現病歴：半年前から全身倦怠感を自覚していた。1 か月前から37℃前半の微熱と乾性咳嗽とが出現した。2 週前に自<br/>宅近くの診療所を受診し総合感冒薬を処方されたが改善しなかった。そのころから体温は38℃を超えるようにな<br/>り、1 週前から階段昇降時に呼吸困難を自覚するようになった。精査のため診療所から紹介されて受診した。<br/>既往歴：22 歳時にB 型急性肝炎。35 歳時に帯状疱疹。<br/>生活歴：会社員。独身。一人暮らし。喫煙歴はない。飲酒は機会飲酒。<br/>家族歴：父親がうつ病で通院治療中。<br/>現　症：意識は清明。身長173cm、体重58kg（半年前は68kg）。体温38.6℃。脈拍96/ 分、整。血圧104/58mmHg。<br/>呼吸数20/ 分。SpO2 94％（room air）。前額と鼻唇溝とに黄白色の鱗屑を伴う紅斑を認める。眼瞼結膜と眼球結膜<br/>とに異常を認めない。口腔内に多発する白苔を認める。頸静脈の怒張を認めない。径1 ～2cm のリンパ節を右頸<br/>部に7 個、左頸部に5 個触知する。心音に異常を認めない。両側の胸部にfine crackles を聴取する。腹部は平坦、<br/>軟で、肝・脾を触知しない。腸雑音は正常である。下腿に浮腫を認めない。<br/>検査所見：血液所見：赤血球454 万、Hb 15.1g/dL、Ht 42％、白血球3,100、血小板12 万。血液生化学所見：総ビリ<br/>ルビン0.9mg/dL、クレアチニン1.0mg/dL。免疫血清学所見：CRP 0.6mg/dL、β-D- グルカン486pg/mL（基準<br/>10 以下）。動脈血ガス分析（room air）：pH 7.47、PaCO2 34Torr、PaO2 76Torr、HCO3<br/>－ 24mEq/L。胸部エック<br/>ス線写真（A）と胸部CT（B）とを示す。</span><br/><strong>肺病変の原因として最も考えられるのはどれか。</strong>",
